// runState is what the State column shows for an agent.
type runState int

const (
	stateUnknown runState = iota
	stateRunning
	stateIdle
	stateDone
)

// label returns the text shown in the State column.
func (s runState) label() string {
	switch s {
	case stateRunning:
		return "running"
	case stateIdle:
		return "idle"
	case stateDone:
		return "done"
	default:
		return "unknown"
	}
}

